// src/server/auth.ts
var scrypt = promisify(crypto2.scrypt);
var SCRYPT = { N: 16384, r: 8, p: 1 };
var SESSION_COOKIE = "asa_session";
var SESSION_DAYS = 30;
var MAX_FAILURES = 5;
var LOCK_MINUTES = 15;
async function hashPassword(password) {
  const salt = crypto2.randomBytes(16);
  const hash = await scrypt(password, salt, 64, SCRYPT);
  return `scrypt$${SCRYPT.N}$${SCRYPT.r}$${SCRYPT.p}$${salt.toString("base64")}$${hash.toString("base64")}`;
}
async function verifyPassword(password, stored) {
  const [alg, n, r, p, saltB64, hashB64] = stored.split("$");
  if (alg !== "scrypt") return false;
  const expected = Buffer.from(hashB64, "base64");
  const actual = await scrypt(password, Buffer.from(saltB64, "base64"), expected.length, { N: Number(n), r: Number(r), p: Number(p) });
  return actual.length === expected.length && crypto2.timingSafeEqual(actual, expected);
}
function passwordProblems(pw) {
  if (pw.length < 10) return "A senha precisa ter pelo menos 10 caracteres.";
  if (!/[A-Za-z]/.test(pw) || !/\d/.test(pw)) return "Use letras e n\xFAmeros na senha.";
  return null;
}
function generatePassword() {
  const alphabet = "ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz23456789";
  const bytes = crypto2.randomBytes(14);
  let out = "";
  for (const b of bytes) out += alphabet[b % alphabet.length];
  return out.slice(0, 4) + "-" + out.slice(4, 9) + "-" + out.slice(9) + "7";
}
var sha256 = (v) => crypto2.createHash("sha256").update(v).digest("hex");
function effectivePermissions(role, extra) {
  if (role === "admin") return [...ALL_PERMISSIONS];
  const set = new Set(ROLE_DEFAULTS[role] ?? []);
  for (const p of extra) if (CONFIGURABLE_PERMISSIONS.includes(p)) set.add(p);
  return [...set];
}
function toSessionUser(u) {
  return {
    id: u.id,
    name: u.name,
    email: u.email,
    role: u.role,
    timezone: u.timezone,
    phone: u.phone,
    permissions: effectivePermissions(u.role, parseJson(u.extra_permissions, [])),
    mustChangePassword: !!u.must_change_password
  };
}
function getUserById(id) {
  const u = get("SELECT * FROM users WHERE id = ? AND active = 1", id);
  return u ? toSessionUser(u) : null;
}
function attemptKey(email, ip) {
  return `${email.toLowerCase()}|${ip}`;
}
function checkLocked(key) {
  const row = get("SELECT locked_until FROM login_attempts WHERE key = ?", key);
  if (row?.locked_until && row.locked_until > nowIso()) {
    throw new HttpError(429, "Muitas tentativas de acesso. Aguarde alguns minutos e tente novamente.");
  }
}
function registerFailure(key) {
  const now = nowIso();
  const row = get("SELECT failures, first_failure_at FROM login_attempts WHERE key = ?", key);
  const windowStart = new Date(Date.now() - LOCK_MINUTES * 6e4).toISOString();
  if (!row || row.first_failure_at < windowStart) {
    run("INSERT OR REPLACE INTO login_attempts (key, failures, first_failure_at, locked_until) VALUES (?, 1, ?, NULL)", key, now);
    return;
  }
  const failures = row.failures + 1;
  const lockedUntil = failures >= MAX_FAILURES ? new Date(Date.now() + LOCK_MINUTES * 6e4).toISOString() : null;
  run("UPDATE login_attempts SET failures = ?, locked_until = ? WHERE key = ?", failures, lockedUntil, key);
}
async function login(email, password, ip, userAgent) {
  const key = attemptKey(email, ip);
  checkLocked(key);
  const u = get("SELECT * FROM users WHERE email = ? COLLATE NOCASE", email.trim());
  const ok = u && u.active ? await verifyPassword(password, u.password_hash) : (await hashPassword(password), false);
  if (!u || !ok) {
    registerFailure(key);
    audit(u?.id ?? null, "login_falhou", "user", u?.id ?? null, { email }, ip);
    throw new HttpError(401, "E-mail ou senha incorretos.");
  }
  run("DELETE FROM login_attempts WHERE key = ?", key);
  const token = crypto2.randomBytes(32).toString("base64url");
  const now = nowIso();
  const expires = new Date(Date.now() + SESSION_DAYS * 864e5).toISOString();
  run(
    "INSERT INTO sessions (token_hash, user_id, created_at, expires_at, last_seen_at, user_agent, ip) VALUES (?, ?, ?, ?, ?, ?, ?)",
    sha256(token),
    u.id,
    now,
    expires,
    now,
    userAgent.slice(0, 300),
    ip
  );
  run("UPDATE users SET last_login_at = ? WHERE id = ?", now, u.id);
  audit(u.id, "login", "user", u.id, {}, ip);
  return { token, user: toSessionUser(u) };
}
function sessionUser(token) {
  if (!token) return null;
  const row = get(
    "SELECT id, user_id, expires_at, last_seen_at FROM sessions WHERE token_hash = ?",
    sha256(token)
  );
  if (!row) return null;
  if (row.expires_at < nowIso()) {
    run("DELETE FROM sessions WHERE id = ?", row.id);
    return null;
  }
  if (Date.now() - Date.parse(row.last_seen_at) > 5 * 6e4) run("UPDATE sessions SET last_seen_at = ? WHERE id = ?", nowIso(), row.id);
  return getUserById(row.user_id);
}
function logout(token) {
  if (token) run("DELETE FROM sessions WHERE token_hash = ?", sha256(token));
}
function revokeUserSessions(userId, exceptToken) {
  if (exceptToken) run("DELETE FROM sessions WHERE user_id = ? AND token_hash <> ?", userId, sha256(exceptToken));
  else run("DELETE FROM sessions WHERE user_id = ?", userId);
}
function sessionCookie(token, secure) {
  return `${SESSION_COOKIE}=${token}; Path=/; HttpOnly; SameSite=Lax; Max-Age=${SESSION_DAYS * 86400}${secure ? "; Secure" : ""}`;
}
function clearSessionCookie() {
  return `${SESSION_COOKIE}=; Path=/; HttpOnly; SameSite=Lax; Max-Age=0`;
}
function audit(userId, action, entity, entityId, detail, ip) {
  run(
    "INSERT INTO audit_trail (user_id, action, entity, entity_id, detail, ip, created_at) VALUES (?, ?, ?, ?, ?, ?, ?)",
    userId,
    action,
    entity,
    entityId,
    JSON.stringify(detail ?? {}),
    ip ?? null,
    nowIso()
  );
}
function requirePerm(user, perm) {
  if (!user) throw new HttpError(401, "Sess\xE3o expirada. Entre novamente.");
  const perms = Array.isArray(perm) ? perm : [perm];
  if (!perms.some((p) => user.permissions.includes(p))) throw new HttpError(403, "Voc\xEA n\xE3o tem permiss\xE3o para esta a\xE7\xE3o.");
}
function can(user, perm) {
  return !!user && user.permissions.includes(perm);
}
function listUsers() {
  return all("SELECT * FROM users ORDER BY role, name").map((u) => ({
    ...toSessionUser(u),
    active: !!u.active,
    extraPermissions: parseJson(u.extra_permissions, []),
    createdAt: u.created_at,
    lastLoginAt: u.last_login_at
  }));
}

