      d2.actions.map((a) => [a.title + (a.description ? ` \u2014 ${a.description}` : ""), ACTION_ORIGINS[a.origin], a.responsible_name ?? "\u2014", a.due_date ? formatDateBR(a.due_date) : "\u2014", ACTION_STATUSES[a.status], `${a.progress}%`])
