async function visitsMeetingsPdf(label, items) {
  const doc = await Doc.create(`Visitas t\xE9cnicas e reuni\xF5es \u2014 ${label}`);
  doc.h1("Relat\xF3rio de visitas t\xE9cnicas e reuni\xF5es", label);
  doc.kpis([
    { label: "Visitas t\xE9cnicas", value: String(items.filter((i) => CATEGORIES[i.event.category].group === "visita").length) },
    { label: "Reuni\xF5es", value: String(items.filter((i) => i.event.category === "reuniao" || i.event.category === "visita_reuniao").length) },
    { label: "Conclu\xEDdas", value: String(items.filter((i) => i.event.status === "concluido").length), tone: "ok" },
    { label: "A\xE7\xF5es derivadas", value: String(items.reduce((s, i) => s + i.actions.length, 0)) }
  ]);
  if (!items.length) doc.para("Nenhuma visita t\xE9cnica ou reuni\xE3o no per\xEDodo.", { color: MUTED });
  for (const it of items) {
    const e = it.event;
    const det = e.details ?? {};
    doc.h2(`${formatPeriod(e.start_date, e.end_date)} \u2014 ${e.title}`);
    doc.para(`${CATEGORIES[e.category].label} \xB7 ${place2(e)} \xB7 ${STATUSES[e.status].label} \xB7 Respons\xE1vel: ${e.responsible_name ?? "A definir"}`, { color: MUTED, size: 9 });
    const fields = [
      ["Objetivo", det.objective],
      ["Atividades planejadas", det.plannedActivities],
      ["Resultado da visita", det.result],
      ["Pend\xEAncias identificadas", det.findings],
      ["Encaminhamentos", det.referrals],
      ["Pauta", det.agenda],
      ["Ata", det.minutes],
      ["Decis\xF5es", det.decisions]
    ];
    const filled = fields.filter(([, v]) => v && String(v).trim());
    if (!filled.length) doc.para("Detalhes ainda n\xE3o registrados.", { color: MUTED, size: 9 });
    filled.forEach(([k, v]) => doc.para(`${k}: ${v}`, { size: 9.5 }));
    const done = it.checklist.filter((c) => c.done).length;
    doc.para(`Checklist: ${done} de ${it.checklist.length} itens conclu\xEDdos.`, { size: 9, color: MUTED });
    if (it.participants.length) doc.para(`Participantes: ${it.participants.map((p) => `${p.name} (${ATTENDANCE[p.attendance].toLowerCase()})`).join(", ")}`, { size: 9 });
    if (it.actions.length) {
      doc.table(
        [{ header: "Tarefa / encaminhamento", width: 230 }, { header: "Respons\xE1vel", width: 100 }, { header: "Prazo", width: 60 }, { header: "Status", width: 70 }, { header: "%", width: 35 }],
        it.actions.map((a) => [a.title, a.responsible_name ?? "\u2014", a.due_date ? formatDateBR(a.due_date) : "\u2014", ACTION_STATUSES[a.status], `${a.progress}%`])
      );
    }
    it.comments.slice(0, 5).forEach((c) => doc.bullet(`${formatDateBR(c.created_at.slice(0, 10))} \xB7 ${c.user_name ?? "\u2014"}: ${c.text}`, LINE));
  }
  return doc.finish();
}

